UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{fsc,whyChoose}', to_jsonb('Vi hjälper tillverkande och distribuerande verksamheter att framgångsrikt implementera D365 Supply Chain Management. Vi fokuserar på att förvandla affärsmål till fungerande processer och systemstöd med långsiktigt fokus.'::text), true), '{fsc,keyPoints}', jsonb_build_array('Expertis inom D365 för tillverkning/distribution.', 'Integrerar AI och automatisering där det ger nytta.', 'Stödjer hela systemets livscykel.', 'Fokus affärsmål och verksamhetsnytta.'), true) WHERE id = 'fe117b80-6acd-49c0-bab0-6fda75f25894'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{bc,whyChoose}', to_jsonb('Vi erbjuder en trygg och lokalt förankrad partner för Business Central, med fokus på att maximera nyttan för tillverkande företag, grossister och byggföretag. Vi säkerställer effektiva projekt som driver er verksamhetsutveckling.'::text), true), '{bc,keyPoints}', jsonb_build_array('Komplett erbjudande, förstudie till utveckling.', 'Effektiva projekt med tydliga leveranser.', 'Lång erfarenhet, starkt engagemang.', 'Maximerar värdet av er Business Central-investering.'), true) WHERE id = 'd863d43e-f5a7-461a-a289-ba285b905d9e'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{bc,whyChoose}', to_jsonb('Vi erbjuder en beprövad lösning med Business Central, anpassad för er bransch, som effektiviserar era affärsprocesser och stödjer er tillväxt.'::text), true), '{bc,keyPoints}', jsonb_build_array('Digitaliserar processer specifikt för er bransch.', 'Djup förståelse för mode och textil.', 'Optimerar lagerhantering och leveranskedjor.', 'Skalbar systemlösning för er verksamhet.'), true) WHERE id = '67211d79-5e9e-4113-b6c2-ac77f54fc17b'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{bc,whyChoose}', to_jsonb('Vi erbjuder kontinuitet i våra kundrelationer, där samma konsulter följer dig från start till mål. Detta säkerställer en djup förståelse för era processer och ger ett förutsägbart resultat för er Business Central-lösning.'::text), true), '{bc,keyPoints}', jsonb_build_array('Vi erbjuder kontinuerligt stöd för Business Central.', 'Vi har erfarenhet av handel och distribution.', 'Vi tillhandahåller lösningar för affärsprocesser.', 'Vi erbjuder implementation och support.'), true) WHERE id = '731f9c05-c293-4842-ac40-19fb610eaeac'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{bc,whyChoose}', to_jsonb('Vi erbjuder paketerade Business Central-lösningar anpassade för transport, logistik, tillverkning och IT-konsulting, vilket ger er snabb affärsnytta. Våra branschspecifika lösningar minskar implementeringstid och risk.'::text), true), '{bc,keyPoints}', jsonb_build_array('Paketerat Business Central-erbjudande.', 'Stöd för PrintVis (grafisk industri).', 'Transport Ekonomi (transportbranschen).', 'Färre anpassningar, snabbare implementering.'), true) WHERE id = 'cfe135f8-b2bf-4740-9f26-389bca040715'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{fsc,whyChoose}', to_jsonb('Vi erbjuder globalt skalbara lösningar för Finance & Supply Chain Management anpassade för tillverknings- och processindustrin i norra Europa, vilket säkrar er affärsnytta.'::text), true), '{fsc,keyPoints}', jsonb_build_array('Vi hanterar komplexa, globala försörjningskedjor.', 'Vi skapar kostnadseffektiva lösningar för er verksamhet.', 'Vi optimerar ekonomistyrning och logistikhantering.', 'Vi har erfarenhet av flera globala implementeringar.'), true) WHERE id = 'cfe135f8-b2bf-4740-9f26-389bca040715'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{sales,whyChoose}', to_jsonb('Vi hjälper stora, komplexa organisationer inom tillverknings- och offentlig sektor att personalisera kundresan. Vi anpassar Sales och Customer Insights för era globala verksamhetsbehov och komplexa processer.'::text), true), '{sales,keyPoints}